3		GameHistoryRepository,
4	} from "../../domain/game/ports/GameHistoryRepository";
5	import type { GameItemSelectionService } from "../../domain/game/services/GameItemSelectionService";
6	import type {
7		GameHistoryEntry,
8		GameItem,
9		GameRatingRecord,
10		GameRoundConfig,
11		GameRoundSummary,
12		RandomSource,
13	} from "../../domain/game/types";
14	import type { RecallRating } from "../../domain/shared/types";
15	
16	const ALL_RATINGS: readonly RecallRating[] = [1, 2, 3, 4, 5];
17	
18	/** Ratings counting as "recalled" toward accuracy — Good and Easy only. */
19	const CORRECT_RATINGS: ReadonlySet<RecallRating> = new Set([4, 5]);
20	
21	/**
22	 * The item's identity: a `symbolCharacter` for a symbol item, a `thaiWord`
23	 * for a word item — matches the dedupe key each `GameItemSource` uses (see
24	 * CONTEXT.md, GameRatingRecord's `itemKey` doc comment). Prefixed with
25	 * `kind` because a Mix round draws from both pools at once, and a symbol
26	 * character can coincide with a vocab word's exact Thai spelling (e.g. "ณ"
27	 * is both a consonant and a one-character preposition) — without the
28	 * prefix, rating that symbol and that word as two separate items in the
29	 * same round would silently collapse into one record in `recordRating`'s
30	 * de-dupe below, undercounting the round.
31	 */
32	function itemKeyOf(item: GameItem): string {
33		return `${item.kind}:${item.kind === "symbol" ? item.symbolCharacter : item.thaiWord}`;
34	}
35	
36	/**
37	 * A round's ratings, as recorded so far. Every function here is a pure
38	 * function of the arguments it is given — no round-in-progress state ever
39	 * lives on this class, matching `ConductReviewUseCase`/`ReviewService`'s own
40	 * caller-holds-the-session convention (see CONTEXT.md). `AppContext.tsx`
41	 * wires this up as one long-lived singleton; a singleton holding mutable
42	 * per-round state would leak ratings between rounds and between mounts.
43	 *
44	 * No `CardRepository` is ever received here — only `GameItemSelectionService`
45	 * (which wraps it) and `GameHistoryRepository`. There is therefore no code
46	 * path through this use case that could ever call `CardRepository.save` or
47	 * `ReviewableCard.recordReview`: the SRS-isolation guarantee is structural,
48	 * not merely a rule nobody happens to break.
49	 */
50	export class PlayGameUseCase {
51		/**
52		 * Tracks which `GameRoundSummary` objects have already been persisted, so
53		 * that finishing/saving the same completed round twice (a duplicate
54		 * effect run, a duplicate button press) does not append a duplicate
55		 * history entry. Keyed by object identity, not content: two genuinely
56		 * distinct rounds that happen to produce an identical summary are still
57		 * two history entries. A `WeakSet` holds no strong reference, so it
58		 * never keeps a finished round's data alive past the caller's own use of
59		 * it — this is bookkeeping for `saveHistory`'s own idempotency, not
60		 * round-in-progress state.
61		 */
62		private readonly savedSummaries = new WeakSet<GameRoundSummary>();
63	
64		constructor(
65			private readonly selectionService: GameItemSelectionService,
66			private readonly historyRepository: GameHistoryRepository,
67		) {}
68	
69		startRound(config: GameRoundConfig, rng?: RandomSource): GameItem[] {
70			return this.selectionService.selectRound(config, rng);
71		}
72	
73		/**
74		 * Returns a new ratings array with `itemIndex`'s rating set to `rating`,
75		 * overwriting any prior rating for that same index rather than appending
76		 * a second record for it — recording twice for one item (a stray global
77		 * keypress landing on top of a click, see CONTEXT.md) must not double-
78		 * count that item in the finished summary.
79		 */
80		recordRating(
81			items: readonly GameItem[],
82			ratings: readonly GameRatingRecord[],
83			itemIndex: number,
84			rating: RecallRating,
85		): GameRatingRecord[] {
86			const item = items[itemIndex];
87			if (!item) return [...ratings];
88	
89			const itemKey = itemKeyOf(item);
90			const record: GameRatingRecord = {
91				itemKey,
92				kind: item.kind,
93				challengeDirection: item.challengeDirection,
94				rating,
95			};
96	
97			return [...ratings.filter((r) => r.itemKey !== itemKey), record];
98		}
99	
100		/**
101		 * `accuracy` counts only ratings 4 (Good) and 5 (Easy) as correct — a
102		 * deliberately different, stricter threshold from
103		 * `ReviewService.endReviewSession`'s `rating >= 3`, and rounded half-up.
104		 * `null` if and only if no rating was recorded, distinct from a rated
105		 * round where none of the ratings were Good/Easy (`accuracy: 0`).
106		 */
107		finishRound(ratings: readonly GameRatingRecord[]): GameRoundSummary {
108			const ratingCounts = ALL_RATINGS.reduce(
109				(counts, value) => {
110					counts[value] = ratings.filter((r) => r.rating === value).length;
111					return counts;
112				},
113				{} as Record<RecallRating, number>,
114			);
115	
116			const ratedCount = ratings.length;
117			const correctCount = ratings.filter((r) =>
118				CORRECT_RATINGS.has(r.rating),
119			).length;
120			const accuracy =
121				ratedCount === 0 ? null : Math.round((correctCount / ratedCount) * 100);
122	
123			return { ratingCounts, ratedCount, accuracy };
124		}
125	
126		saveHistory(
127			config: Pick<GameRoundConfig, "pools" | "itemCount">,
128			summary: GameRoundSummary,
129		): void {
130			if (this.savedSummaries.has(summary)) return;
131			this.savedSummaries.add(summary);
132	
133			const entry: GameHistoryEntry = {
134				id: crypto.randomUUID(),
135				playedAt: new Date().toISOString(),
136				pools: config.pools,
137				itemCount: config.itemCount,
138				summary,
139			};
140			this.historyRepository.save(entry);
141		}
142	
143		getHistory(): GameHistoryListResult {
144			return this.historyRepository.list();
145		}
146	}
