		setCountInput(
			eligibleCount > 0
				? String(Math.min(DEFAULT_ITEM_COUNT, eligibleCount))
				: "",
		);
	}, [poolChoice]);
	const history = useMemo(
		() => (phase === "setup" ? game.getHistory() : null),
		[game, phase],
	);

