	game: PlayGameUseCase,
	pools: readonly GameCardPool[],
	prioritizeWeakItems: boolean = false,
): number {
	return game.startRound({
		pools,
		itemCount: Number.MAX_SAFE_INTEGER,
		prioritizeWeakItems,
		inputMode: "draw",
	}).length;
