		expect(document.activeElement).toBe(wordsChoice);
		fireEvent.click(wordsChoice);
		expect(wordsChoice.checked).toBe(true);
		expect(symbolsChoice.checked).toBe(false);

		mixChoice.focus();
		expect(document.activeElement).toBe(mixChoice);
		fireEvent.click(mixChoice);
		expect(mixChoice.checked).toBe(true);
		expect(wordsChoice.checked).toBe(false);
	});

	// Task 3.2 AC1
	it("checkbox is unchecked by default and an unchecked round draws the unweighted item set", () => {
		const weakCard = scriptCardWith("ม", 1.3, 4, 5);
		const strongCard = scriptCardWith("น", 2.8, 0, 8);
		const freshCard = scriptCardWith("ง", 2.5, 0, 0);
		const cardRepo = new StorageCardRepository(new InMemoryStorage());
		cardRepo.saveAll([strongCard, freshCard, weakCard]);
		const game = new PlayGameUseCase(
			new GameItemSelectionService(
				[new SymbolGameItemSource(cardRepo)],
				cardRepo,
			),
			new StorageGameHistoryRepository(
				new InMemoryJsonStore<GameHistoryEntry[]>(),
			),
		);
		renderWithApp(<GamePage />, { game });

		// AC1a: checkbox is unchecked by default
		const toggle = screen.getByLabelText("Prioritize weak items") as HTMLInputElement;
		expect(toggle.checked).toBe(false);

		// AC1b: an unweighted round (roll 0.75 of 3 items, uniform distribution)
		// lands on the second item in draw order. With the cards in [strong, fresh,
		// weak] order and roll 0.75 picking the second-to-last, uniform lands on
		// fresh. Weighting would land on weak (its weight is > 2x the other two
		// combined), so this only passes with weighting *off* — confirming the
		// unchecked toggle disables weighting.
		setCount("1");
		startRound();

		const firstItem = screen.getByText("ง"); // fresh symbol, not weak
		expect(firstItem).toBeTruthy();
	});

	// Task 3.2 AC2
	it("checkbox checked draws the weak-biased item set matching task 3.1's expectation", () => {
		const {
			WEAK_SYMBOL,
			FRESH_SYMBOL,
			STRONG_SYMBOL,
			WEAK_STRONG_FRESH_CARDS,
			weightedSeed,
		} = require("../../domain/game/test-fixtures/weakStrongFixture");
		const cardRepo = new StorageCardRepository(new InMemoryStorage());
		cardRepo.saveAll([...WEAK_STRONG_FRESH_CARDS]);
		const game = new PlayGameUseCase(
			new GameItemSelectionService(
				[new SymbolGameItemSource(cardRepo)],
				cardRepo,
			),
			new StorageGameHistoryRepository(
				new InMemoryJsonStore<GameHistoryEntry[]>(),
			),
		);
		renderWithApp(<GamePage />, { game });

		// Check the toggle
		const toggle = screen.getByLabelText("Prioritize weak items") as HTMLInputElement;
		fireEvent.click(toggle);
		expect(toggle.checked).toBe(true);

		// With weighting on and the weighted seed (roll 0.5), the draw always
		// lands on the weak item first, regardless of draw order.
		setCount("1");
		startRound();

		const firstItem = screen.getByText(WEAK_SYMBOL);
		expect(firstItem).toBeTruthy();
	});

	// Task 3.2 AC3
	it("toggle + zero-eligible-pool interaction: start stays blocked regardless of toggle state", () => {
		renderWithApp(<GamePage />);
		const toggle = screen.getByLabelText("Prioritize weak items") as HTMLInputElement;

		// No eligible symbols: start blocked with toggle off.
		expect(screen.getByText(/No symbols to practice yet/)).toBeTruthy();
		expect(screen.queryByRole("button", { name: "Start Round" })).toBeNull();

		// Toggle on, still no eligible items, still blocked with same message.
		fireEvent.click(toggle);
		expect(toggle.checked).toBe(true);
		expect(screen.getByText(/No symbols to practice yet/)).toBeTruthy();
		expect(screen.queryByRole("button", { name: "Start Round" })).toBeNull();
	});

	// Task 3.2 AC4
	it("prioritize-weak-items checkbox is accessibly labeled and keyboard-operable", () => {
		renderWithApp(<GamePage />, {}, { symbols: ["ม"] });

		const toggle = screen.getByLabelText("Prioritize weak items") as HTMLInputElement;
		expect(toggle.type).toBe("checkbox");
		expect(toggle.checked).toBe(false);

		toggle.focus();
		expect(document.activeElement).toBe(toggle);

		fireEvent.click(toggle);
		expect(toggle.checked).toBe(true);

		fireEvent.click(toggle);
		expect(toggle.checked).toBe(false);
	});
});

